import json
import os
from typing import Iterator, Optional, Union
import boto3
from botocore.exceptions import NoCredentialsError, ClientError

class InputReader:
    def __init__(self, source: Union[str, bytes], fail_on_missing: bool = False):
        self.source = source
        self.fail_on_missing = fail_on_missing
        self.content = None

    def _load_from_file(self) -> None:
        if not os.path.exists(self.source):
            if self.fail_on_missing:
                raise FileNotFoundError(f"File {self.source} not found.")
            else:
                self.content = b""
                return
        with open(self.source, 'rb') as f:
            self.content = f.read()

    def _load_from_bucket(self) -> None:
        s3 = boto3.client('s3')
        bucket_name, key = self._parse_s3_path(self.source)
        try:
            response = s3.get_object(Bucket=bucket_name, Key=key)
            self.content = response['Body'].read()
        except (NoCredentialsError, ClientError) as e:
            if self.fail_on_missing:
                raise FileNotFoundError(f"Bucket {bucket_name} or key {key} not found.") from e
            else:
                self.content = b""

    def _parse_s3_path(self, path: str) -> tuple:
        if not path.startswith("s3://"):
            raise ValueError("Invalid S3 path.")
        parts = path[5:].split('/', 1)
        if len(parts) != 2:
            raise ValueError("Invalid S3 path.")
        return parts[0], parts[1]

    def load(self) -> None:
        if self.source.startswith("s3://"):
            self._load_from_bucket()
        else:
            self._load_from_file()

    def __iter__(self) -> Iterator[bytes]:
        if self.content is None:
            self.load()
        return iter(self.content)

    @classmethod
    def from_json(cls, json_str: str) -> 'InputReader':
        data = json.loads(json_str)
        return cls(source=data['source'], fail_on_missing=data.get('fail_on_missing', False))

    def to_json(self) -> str:
        return json.dumps({
            'source': self.source,
            'fail_on_missing': self.fail_on_missing
        })

